const DEFAULT_PORTFOLIO = { cash: 10000, startingCash: 10000, positions: {}, transactions: [] };

function useStoredState(key, fallback) {
  const [value, setValue] = useState(fallback);
  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const res = await window.storage.get(key, false);
        if (!cancelled && res && res.value) setValue(JSON.parse(res.value));
      } catch (e) {
        // no stored value yet -- keep fallback
      } finally {
        if (!cancelled) setLoaded(true);
      }
    })();
    return () => { cancelled = true; };
  }, [key]);
  const persist = useCallback(async (next) => {
    setValue(next);
    try { await window.storage.set(key, JSON.stringify(next), false); }
    catch (e) { /* best-effort */ }
  }, [key]);
  return [value, persist, loaded];
}

/* ============================================================================
   ANIMATED NUMBERS -- ease-out count-up from the previous value to the next
   whenever `target` changes, so key stats feel alive instead of snapping.
   ============================================================================ */
function useCountUp(target, duration = 700) {
  const [display, setDisplay] = useState(target);
  const fromRef = useRef(target);
  const rafRef = useRef(null);

  useEffect(() => {
    if (target == null || !isFinite(target)) { setDisplay(target); return; }
    const from = fromRef.current == null || !isFinite(fromRef.current) ? target : fromRef.current;
    const start = performance.now();
    cancelAnimationFrame(rafRef.current);
    const tick = (now) => {
      const t = Math.min(1, (now - start) / duration);
      const eased = 1 - Math.pow(1 - t, 3);
      setDisplay(from + (target - from) * eased);
      if (t < 1) rafRef.current = requestAnimationFrame(tick);
      else fromRef.current = target;
    };
    rafRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(rafRef.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [target, duration]);

  return display;
}

