function LearnCard({ topic, expanded, onToggle }) {
  const color = LEARN_CATEGORIES[topic.category] || COLOR.accent;
  return (
    <div className="ip-card ip-learn-card" onClick={() => onToggle(topic.id)}>
      <span className="ip-badge" style={{ background: `${color}1a`, color }}>{topic.category}</span>
      <div style={{ fontWeight: 700, fontSize: 15, margin: "10px 0 6px" }}>{topic.title}</div>
      <div style={{ fontSize: 13, color: COLOR.muted, lineHeight: 1.5 }}>{topic.summary}</div>
      {expanded && (
        <div style={{ fontSize: 13.5, lineHeight: 1.6, marginTop: 12, paddingTop: 12, borderTop: `1px solid ${COLOR.line}` }}>
          {topic.body}
        </div>
      )}
      <div className="ip-link" style={{ fontSize: 12, marginTop: 10, display: "inline-block" }}>
        {expanded ? "Show less" : "Read more"}
      </div>
    </div>
  );
}

